/** A validated submission, with defaults applied. */
export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface FieldError {
  field: string;
  message: string;
}

export type ValidationResult =
  | { ok: true; payload: Submission; idempotencyKey: string | undefined }
  | { ok: false; fields: FieldError[] };

export interface RawSubmission {
  contentType: string | undefined;
  rawBody: string;
  /** True when the body exceeded the size limit and was not kept. */
  tooLarge: boolean;
  /** The Idempotency-Key header, or undefined when it is absent. An empty string is present but invalid. */
  idempotencyKey: string | undefined;
}

const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
const JSON_CONTENT_TYPE = /^application\/json\s*(;|$)/i;

const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

/** Validates a submission and collects every problem, naming each offending field. */
export function validateSubmission(raw: RawSubmission): ValidationResult {
  const fields: FieldError[] = [];
  const add = (field: string, message: string) => fields.push({ field, message });

  let obj: Record<string, unknown> | undefined;
  if (raw.tooLarge) {
    add('body', 'Request body is too large');
  } else if (raw.contentType === undefined || !JSON_CONTENT_TYPE.test(raw.contentType.trim())) {
    add('body', 'Content-Type must be application/json');
  } else {
    let parsed: unknown;
    try {
      parsed = JSON.parse(raw.rawBody);
    } catch {
      add('body', 'Body is not valid JSON');
    }
    if (parsed !== undefined || raw.rawBody.trim() === 'null') {
      if (isPlainObject(parsed)) obj = parsed;
      else add('body', 'Body must be a JSON object');
    }
  }

  if (raw.idempotencyKey !== undefined && !IDEMPOTENCY_KEY.test(raw.idempotencyKey)) {
    add('Idempotency-Key', 'Must be 1 to 128 characters: letters, digits, "_" or "-"');
  }

  let input: string | undefined;
  let steps: number | undefined = 5;
  let failAttempts: number | undefined = 0;

  if (obj) {
    for (const key of Object.keys(obj)) {
      if (!KNOWN_FIELDS.has(key)) add(key, 'Unknown field');
    }

    const value = obj.input;
    if (typeof value !== 'string') {
      add('input', 'Must be a string');
    } else if (value.length < 1 || value.length > 1000) {
      add('input', 'Must be between 1 and 1000 characters');
    } else if (value.trim() === '') {
      add('input', 'Must not be only whitespace');
    } else {
      input = value;
    }

    steps = intField(obj, 'steps', 1, 20, 5, add);
    failAttempts = intField(obj, 'failAttempts', 0, 5, 0, add);
  }

  if (fields.length > 0 || input === undefined || steps === undefined || failAttempts === undefined) {
    return { ok: false, fields: fields.length > 0 ? fields : [{ field: 'body', message: 'Invalid request body' }] };
  }
  return { ok: true, payload: { input, steps, failAttempts }, idempotencyKey: raw.idempotencyKey };
}

function intField(
  obj: Record<string, unknown>,
  name: string,
  min: number,
  max: number,
  fallback: number,
  add: (field: string, message: string) => void,
): number | undefined {
  if (!(name in obj)) return fallback;
  const value = obj[name];
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    add(name, `Must be an integer from ${min} to ${max}`);
    return undefined;
  }
  if (value < min || value > max) {
    add(name, `Must be an integer from ${min} to ${max}`);
    return undefined;
  }
  return value;
}

