    add('Idempotency-Key', 'Must be 1 to 128 characters: letters, digits, "_" or "-"');
  }

  let input: string | undefined;
  let steps: number | undefined = 5;
  let failAttempts: number | undefined = 0;

  if (obj) {
    for (const key of Object.keys(obj)) {
      if (!KNOWN_FIELDS.has(key)) add(key, 'Unknown field');
    }

    const value = obj.input;
    if (typeof value !== 'string') {
      add('input', 'Must be a string');
    } else if (value.length < 1 || value.length > 1000) {
      add('input', 'Must be between 1 and 1000 characters');
    } else if (value.trim() === '') {
      add('input', 'Must not be only whitespace');
    } else {
      input = value;
    }

    steps = intField(obj, 'steps', 1, 20, 5, add);
    failAttempts = intField(obj, 'failAttempts', 0, 5, 0, add);
  }

  if (fields.length > 0 || input === undefined || steps === undefined || failAttempts === undefined) {
    return { ok: false, fields: fields.length > 0 ? fields : [{ field: 'body', message: 'Invalid request body' }] };
  }
  return { ok: true, payload: { input, steps, failAttempts }, idempotencyKey: raw.idempotencyKey };
}

function intField(
  obj: Record<string, unknown>,
  name: string,
  min: number,
  max: number,
  fallback: number,
  add: (field: string, message: string) => void,
): number | undefined {
  if (!(name in obj)) return fallback;
  const value = obj[name];
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    add(name, `Must be an integer from ${min} to ${max}`);
    return undefined;
  }
  if (value < min || value > max) {
    add(name, `Must be an integer from ${min} to ${max}`);
    return undefined;
  }
  return value;
}

