import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { inTransaction, isWorkerUp, nowIso, openDatabase, rowToJob, type Job, type JobRow } from './db.ts';
import { validateSubmission, type FieldError, type Submission } from './validate.ts';

const MAX_BODY_BYTES = 1_000_000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

function findJobRow(id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

function findJobRowByKey(key: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as unknown as JobRow | undefined;
}

function samePayload(row: JobRow, p: Submission): boolean {
  return row.input === p.input && row.steps === p.steps && row.fail_attempts === p.failAttempts;
}

type CreateOutcome = { kind: 'created'; job: Job } | { kind: 'replayed'; job: Job } | { kind: 'conflict' };

/** Creates a job, or resolves an Idempotency-Key replay. Runs in one write transaction. */
function createJob(p: Submission, key: string | undefined): CreateOutcome {
  const outcome = inTransaction<CreateOutcome>(db, () => {
    if (key !== undefined) {
      const existing = findJobRowByKey(key);
      if (existing) {
        return samePayload(existing, p) ? { kind: 'replayed', job: rowToJob(existing) } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = nowIso();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
         result_output, error, created_at, updated_at, run_after, idempotency_key)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, 0, ?)`,
    ).run(id, p.input, p.steps, p.failAttempts, now, now, key ?? null);
    return { kind: 'created', job: rowToJob(findJobRow(id)!) };
  });
  return outcome;
}

/** Wraps createJob with a backstop: a UNIQUE violation on the key means a concurrent replay won. */
function createJobOrReplay(p: Submission, key: string | undefined): CreateOutcome {
  try {
    return createJob(p, key);
  } catch (e) {
    const isUnique = e instanceof Error && /UNIQUE constraint failed/.test(e.message);
    if (key !== undefined && isUnique) {
      const existing = findJobRowByKey(key);
      if (existing) {
        return samePayload(existing, p) ? { kind: 'replayed', job: rowToJob(existing) } : { kind: 'conflict' };
      }
    }
    throw e;
  }
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const header = req.headers['idempotency-key'];
  const v = validateSubmission({
    contentType: req.headers['content-type'],
    rawBody: text,
    tooLarge,
    idempotencyKey: header === undefined ? undefined : String(header),
  });
  if (!v.ok) {
    sendError(res, 400, 'invalid_request', 'Invalid request', v.fields);
    return;
  }
  const outcome = createJobOrReplay(v.payload, v.idempotencyKey);
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload');
  } else if (outcome.kind === 'replayed') {
    send(res, 200, outcome.job);
  } else {
    send(res, 201, outcome.job);
  }
}

function handleList(res: ServerResponse): void {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  send(res, 200, { jobs: rows.map(rowToJob) });
}

function handleGet(res: ServerResponse, rawId: string): void {
  let id = rawId;
  try {
    id = decodeURIComponent(rawId);
  } catch {
    // keep the raw segment; it will simply not match
  }
  const row = findJobRow(id);
  if (!row) sendError(res, 404, 'not_found', 'Job not found');
  else send(res, 200, rowToJob(row));
}

function handleHealth(res: ServerResponse): void {
  send(res, 200, { status: 'ok', worker: isWorkerUp(db) ? 'up' : 'down' });
}

function handleUi(res: ServerResponse): void {
  res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
  res.end(uiHtml);
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const jobMatch = /^\/api\/jobs\/([^/]+)$/.exec(pathname);

  let allowed: string[];
  let handler: () => void | Promise<void>;
  if (pathname === '/health') {
    allowed = ['GET'];
    handler = () => handleHealth(res);
  } else if (pathname === '/') {
    allowed = ['GET'];
    handler = () => handleUi(res);
  } else if (pathname === '/api/jobs') {
    allowed = ['GET', 'POST'];
    handler = method === 'POST' ? () => handleCreate(req, res) : () => handleList(res);
  } else if (jobMatch) {
    allowed = ['GET'];
    const rawId = jobMatch[1]!;
    handler = () => handleGet(res, rawId);
  } else {
    sendError(res, 404, 'not_found', 'Not found');
    return;
  }

  if (!allowed.includes(method)) {
    sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here`);
    return;
  }
  await handler();
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (res.headersSent) {
      res.end();
    } else {
      sendError(res, 500, 'internal_error', 'Internal server error');
    }
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  // Force exit if open connections keep the server from closing.
  setTimeout(() => process.exit(0), 2000).unref();
  server.close(() => {
    try {
      db.close();
    } catch {
      // already closed
    }
    process.exit(0);
  });
  server.closeAllConnections();
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

server.listen(port, () => console.log(`server listening on ${port}`));

