import { setTimeout as sleep } from 'node:timers/promises';
import { inTransaction, nowIso, openDatabase, writeHeartbeat, type JobRow } from './db.ts';

/** Simulated per-step duration, in milliseconds. */
const STEP_MS = 100;
/** Delay before a failed attempt is retried, in milliseconds. */
const RETRY_DELAY_MS = 500;
/** Attempts allowed in total before a job is marked failed. */
const MAX_ATTEMPTS = 3;
const IDLE_MS = 200;
const HEARTBEAT_MS = 500;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

writeHeartbeat(db);
const heartbeat = setInterval(() => {
  try {
    writeHeartbeat(db);
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}, HEARTBEAT_MS);

// Only one worker process runs, so any job still marked running was abandoned by a previous worker.
db.prepare(
  "UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'",
).run(nowIso());

/** Claims the oldest runnable queued job and marks it running for a new attempt. */
function claim(): JobRow | undefined {
  return inTransaction(db, () => {
    const row = db
      .prepare("SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1")
      .get(Date.now()) as unknown as JobRow | undefined;
    if (!row) return undefined;
    db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'queued'",
    ).run(nowIso(), row.id);
    return { ...row, status: 'running', attempts: row.attempts + 1, progress_completed: 0 };
  });
}

/** Processes one attempt. Returns early, leaving the job running, if shutdown was requested. */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (attempt >= MAX_ATTEMPTS) {
      db.prepare(
        "UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, updated_at = ? WHERE id = ? AND status = 'running'",
      ).run(nowIso(), job.id);
    } else {
      db.prepare(
        "UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'",
      ).run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    db.prepare("UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'").run(step, nowIso(), job.id);
  }

  db.prepare(
    "UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(job.input.toUpperCase(), job.steps, nowIso(), job.id);
}

console.log('worker started');

while (!stopping) {
  let job: JobRow | undefined;
  try {
    job = claim();
  } catch (e) {
    console.error('claim failed:', e);
  }
  if (!job) {
    await sleep(IDLE_MS);
    continue;
  }
  try {
    await runAttempt(job);
  } catch (e) {
    console.error(`attempt for job ${job.id} failed:`, e);
    await sleep(IDLE_MS);
  }
}

// Shutdown: requeue any job left running so the next worker picks it up at once.
clearInterval(heartbeat);
try {
  db.prepare(
    "UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'",
  ).run(nowIso());
  writeHeartbeat(db, 0);
} catch (e) {
  console.error('shutdown cleanup failed:', e);
}
db.close();
console.log('worker stopped');
process.exit(0);

